content.text:
{
  "name": "QuTech 控制箱 v3",
  "name_en": "QuTech Control Box v3",
  "manufacturer": "QuTech",
  "description": "QuTech 控制箱 v3 是一台可编程实验控制电子设备，用于向内部控制核心下发指令、读取主控制器参数，并支持设备参数初始化与功能测试，适合需要确定性时序与固件级控制的实验场景。",
  "description_en": "The QuTech Control Box v3 is a programmable experimental control instrument used to load instructions into its internal control core, read master-controller parameters, and support parameter initialization and functional testing. It is suited for experiments requiring deterministic timing and firmware-level control.",
  "actions": [
    {
      "action_name": "auto-add_params",
      "description": "定义控制箱中使用的参数项。",
      "description_en": "Define the parameter set used by the control box."
    },
    {
      "action_name": "auto-init_params",
      "description": "初始化控制箱参数。",
      "description_en": "Initialize the control box parameters."
    },
    {
      "action_name": "auto-run_test_suite",
      "description": "运行控制箱测试套件以检查功能。",
      "description_en": "Run the control box test suite to verify functionality."
    },
    {
      "action_name": "auto-get_master_controller_params",
      "description": "读取并解码主控制器参数。",
      "description_en": "Read and decode the master controller parameters."
    },
    {
      "action_name": "auto-load_instructions",
      "description": "向控制箱加载指令序列或汇编程序。",
      "description_en": "Load an instruction sequence or assembly program into the control box."
    }
  ],
  "tag_hints": [
    "programmable control electronics",
    "instruction upload",
    "master controller parameters",
    "firmware-controlled sequencing",
    "FPGA/control core",
    "quantum experiment control"
  ]
}

